package com.multiaceites.controller; import com.multiaceites.service.SaleService; import com.multiaceites.service.ProductService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reportes") @RequiredArgsConstructor public class ReportController{private final SaleService sales;private final ProductService products;@GetMapping("/dashboard") public Object dashboard(){return sales.dashboard();}@GetMapping("/productos-mas-vendidos") public Object top(){return sales.topProducts();}@GetMapping("/ingresos-facturacion") public Object income(){return sales.history();}@GetMapping("/bajo-stock") public Object low(){return products.lowStock();}}
